import{_ as e,o,c as r,ag as n}from"./chunks/plugin-vue_export-helper.BT7B-090.js";const h=JSON.parse('{"title":"Лучшие промышленные практики построения AI-агентов, 10 из 10","description":"","frontmatter":{"site":"pro","title":"Лучшие промышленные практики построения AI-агентов, 10 из 10","date":"2026-10-11T00:00:00.000Z","source":"https://t.me/jfyi_ps/106","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-10-11-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-10"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Лучшие промышленные практики построения AI-агентов, 10 из 10"}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-10-11-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-10"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Лучшие промышленные практики построения AI-агентов, 10 из 10"}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Лучшие промышленные практики построения AI-агентов, 10 из 10\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-10-11-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-10\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-10-11\\"}"]]},"headers":[],"relativePath":"posts/2026-10-11-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-10.md","filePath":"posts/2026-10-11-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-10.md"}'),s={name:"posts/2026-10-11-luchshie-promyshlennye-praktiki-postroeniya-ai-agentov-10.md"};function i(a,t,p,l,g,c){return o(),r("div",null,[...t[0]||(t[0]=[n('<p>Выжимка из книги Ли Боцзе «Глубокое понимание AI Agent: принципы проектирования и инженерная практика» (Pine AI, v2.0, 2026).**</p><ol start="10"><li>Мультиагентное взаимодействие**</li></ol><p>Общий контекст (без потерь, но растёт) vs раздельный (параллелизм, нужна синхронизация: параметры вызова / общая ФС / шина сообщений — аналоги IPC).</p><p><strong>Критерий:</strong> вносит ли взаимодействие НОВУЮ информацию, недоступную одному агенту (тесты/рендер — да; «агенты обсуждают текст» — нет). Бюджет шагов не гарантирует улучшения без «осознания бюджета». Мультиагентность стоит на порядок дороже — считай реалистично.</p><p>Виртуальная ФС — 4 зоны: приватный scratchpad / общее пространство (блокировка) / внешние ресурсы / встроенные read-only. Передавай путь к файлу, не содержимое.</p><p>Плоскость управления: create/cancel/list (fork/kill/ps); статус — через сообщения/файл прогресса, НЕ опрос; мягкое прерывание лучше принудительного; идемпотентная фиксация при гонке успехов; каскадная отмена по дереву.</p><p><strong>Равноправное:</strong> разнообразие ПРОЕКТИРУЙ — однородные агенты дают одинаковую ошибку. «Готово» — заявление, не доказательство без верификатора. Reviewer читает независимые свидетельства, не меняет тесты. Самопроверка без внешней обратной связи не улучшает результат. Дебаты при равном бюджете часто не превосходят одного агента.</p><p><strong>Оркестрация:</strong> &gt;5 подзадач — сильнейшую модель планировщику, контекст менеджера компактный, фиксация по первому проверенному успеху. <strong>Децентрализация</strong> — для устойчивости к единой точке отказа. A2A — для межорганизационного (карточка возможностей + жизненный цикл + непрозрачность).</p><p><strong>Отказы:</strong> агент византийский (лжёт правдоподобно) — нужна независимая проверка по конструкции, не точечные фиксы. Конфликт файла простой (блокировка версий) vs семантический (изолируй копии). Ошибка усиливается при передаче — кросс-проверка рвёт цепь. Однородные агенты совпадают в ошибке — разные модели.</p><p><strong>Примеры задач для мультиагентных систем</strong></p><p>Критерий применимости: мультиагентность оправдана, если взаимодействие вносит <strong>новую информацию</strong>, недоступную одному агенту за один проход (результат теста, рендер, внешний факт) — а не когда несколько агентов просто обсуждают один и тот же текст.</p><ol><li><strong>Ревью кода с исполнением тестов</strong> (Proposer-Reviewer). Ревьюер видит результат прогона тестов/линтера, а не рассуждения автора.</li><li><strong>Генерация презентации/видео с визуальной проверкой</strong>. Reviewer смотрит скриншот рендера (смена модальности), автор своей ошибки в коде рендера не видит.</li><li><strong>Поиск уязвимостей в открытом пространстве</strong> (равноправное/децентрализованное). Разный фокус агентов расширяет покрытие, а не повторяет одно и то же.</li><li><strong>Проект с &gt;5 разнородных подзадач</strong> (оркестрация). Бэкенд/фронтенд/миграции — специализированное знание у каждого агента.</li><li><strong>Техподдержка с двусторонним управлением состоянием</strong>. Проверяет, перечитывает ли агент состояние после изменений другой стороной.</li><li><strong>Обновление базы знаний через PR-модель</strong>. Независимый Reviewer сверяет правку с первоисточником, а не доверяет автору.</li><li><strong>A2A между организациями</strong> (напр. турагентство—авиакомпания). Разные зоны доверия требуют протокола, не общего контекста.</li><li><strong>Делегирование широкого поиска суб-агенту</strong> с изолированным контекстом. В основной контекст возвращается резюме, а не весь шум.</li><li><strong>Параллельная генерация кандидатов с settle-once</strong>. Финализируется первый, прошедший скрытую проверку, не первый заявивший «готово».</li><li><strong>Робототехнический контур с разделением масштабов времени</strong>. Планировщик (минуты) / навык (секунды) / safety-слой (50-1000Гц) физически не могут жить в одном контексте.</li></ol><p><strong>Антипаттерн:</strong> агенты по очереди редактируют один текст или дебатируют на одних и тех же вводных без доступа к новым фактам — самопроверка без внешней обратной связи не улучшает результат, а дебаты при равном бюджете токенов часто не превосходят одного агента.</p><p><strong>Сквозное резюме всей книги:</strong> модель постепенно поглощает функции Harness (медленнее интуиции — обучение месяцы, бизнес ждать не может). Harness-инженерия — практическое воплощение «горького урока» в масштабе инженерного времени: то, что модель делает нестабильно, временно компенсирует Harness; по мере усвоения — Harness упрощается, фронтир сдвигается дальше. Три вопроса, переживающие смену поколений моделей: что агент видит, что может делать, как проверить правильность сделанного.</p>',14)])])}const y=e(s,[["render",i]]);export{h as __pageData,y as default};
